// Snap Vanish engine. Runs inside a hidden extension iframe (extension origin,
// so WASM and local models load regardless of the meeting site's CSP).
// Receives camera frames as ImageBitmaps from inject.js, returns processed ones.
//
// Pipeline per frame:
//   1. Person segmentation (MediaPipe selfie segmenter) on a 256px-wide copy.
//   2. Empty-room photo: a REAL photo of the room (captured from the camera
//      with nobody in view, or uploaded in the popup) is stored in
//      chrome.storage.local under "emptyRoom". Nothing is generated by AI.
//   3. Snap detection (MediaPipe hand landmarker): thumb+middle pinch followed
//      quickly by a release with the middle finger slapping toward the palm,
//      optionally confirmed by a click transient from the microphone.
//   4. Dust effect: a noise-driven dissolve front sweeps the body; each cell
//      it crosses becomes a particle (made of your own pixels) that is blown
//      away and fades to ash, revealing the empty-room photo underneath.
//      Once everything has dissolved the output is just the photo.
//      Reappearing plays it backwards, with particles flying back into place.

import { FilesetResolver, HandLandmarker, ImageSegmenter } from '../lib/vision_bundle.mjs';
import { SnapDetector } from './snap-detector.js';

const GW = 256;               // segmentation / dissolve grid width
const HAND_W = 640;           // hand tracking input width
const FLIGHT = 0.75;          // seconds a returning particle travels
const MAX_PARTICLES = 60000;
const PARENT = window.parent;

let config = {
  enabled: true, gesture: true, audioAssist: true,
  sensitivity: 3, duration: 2.4, wind: 'right', debug: false,
};
let handLandmarker = null;
let segmenter = null;
let ready = false;
let lastTs = 0;
let audioPeakAt = -1e9;
const contexts = new Map();

const post = (msg, transfer) => PARENT.postMessage(msg, '*', transfer || []);
const extUrl = (p) => new URL(p, location.href).href;
const nextTs = () => (lastTs = Math.max(performance.now(), lastTs + 1));
const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
const smoothstep = (a, b, v) => { const t = clamp01((v - a) / (b - a)); return t * t * (3 - 2 * t); };
const rand = (a, b) => a + Math.random() * (b - a);

// ---- Models -----------------------------------------------------------------
// Both models start on the GPU delegate. After a short warm-up the engine
// times them and, if they are slow, tries the CPU (WASM/XNNPACK) delegate and
// keeps whichever is faster. Integrated GPUs that are busy encoding the
// meeting video are often slower than the CPU path.
let fileset = null;
const bench = { phase: 'gpu', n: 0, sum: 0, gpuMs: 0, gpu: null, cpu: null };
const BENCH_FRAMES = 15;

function createModels(delegate) {
  return Promise.all([
    HandLandmarker.createFromOptions(fileset, {
      baseOptions: { modelAssetPath: extUrl('models/hand_landmarker.task'), delegate },
      runningMode: 'VIDEO',
      numHands: 2,
      minHandDetectionConfidence: 0.45,
      minHandPresenceConfidence: 0.45,
      minTrackingConfidence: 0.45,
    }),
    ImageSegmenter.createFromOptions(fileset, {
      baseOptions: { modelAssetPath: extUrl('models/selfie_segmenter_landscape.tflite'), delegate },
      runningMode: 'VIDEO',
      outputConfidenceMasks: true,
      outputCategoryMask: false,
    }),
  ]);
}

async function init() {
  try {
    fileset = await FilesetResolver.forVisionTasks(extUrl('lib/wasm'));
    try {
      [handLandmarker, segmenter] = bench.gpu = await createModels('GPU');
    } catch (err) {
      console.warn('[Snap Vanish] GPU delegate failed, using CPU', err);
      [handLandmarker, segmenter] = await createModels('CPU');
      bench.phase = 'done';
    }
    ready = true;
    post({ type: 'ready' });
    loadRoom();
  } catch (err) {
    console.error('[Snap Vanish] init failed', err);
    post({ type: 'error', message: String(err?.message || err) });
  }
}

const closeModels = (m) => m?.forEach((x) => { try { x.close(); } catch {} });

function recordModelTime(ms) {
  if (bench.phase !== 'gpu' && bench.phase !== 'cpu') return;
  if (++bench.n <= 3) return; // skip warm-up frames
  bench.sum += ms;
  if (bench.n < BENCH_FRAMES + 3) return;
  const avg = bench.sum / BENCH_FRAMES;
  bench.n = 0;
  bench.sum = 0;
  if (bench.phase === 'gpu') {
    bench.gpuMs = avg;
    if (avg < 25) { bench.phase = 'done'; return; } // GPU is plenty fast
    bench.phase = 'loading-cpu';
    createModels('CPU').then((m) => {
      bench.cpu = m;
      [handLandmarker, segmenter] = m;
      bench.phase = 'cpu';
    }).catch(() => { bench.phase = 'done'; });
  } else {
    const useCpu = avg < bench.gpuMs;
    [handLandmarker, segmenter] = useCpu ? bench.cpu : bench.gpu;
    closeModels(useCpu ? bench.gpu : bench.cpu);
    console.info(`[Snap Vanish] model timing GPU ${bench.gpuMs.toFixed(1)} ms, CPU ${avg.toFixed(1)} ms -> ${useCpu ? 'CPU' : 'GPU'}`);
    bench.phase = 'done';
    bench.choice = useCpu ? 'CPU' : 'GPU';
  }
}


// ---- Empty-room photo ---------------------------------------------------------
// Stored by the popup (upload) or by the capture routine below as
//   chrome.storage.local.emptyRoom = { dataUrl, updatedAt, source }
let roomBitmap = null;
let roomVersion = 0;

function dataUrlToBlob(u) {
  const comma = u.indexOf(',');
  const mime = /data:([^;,]+)/.exec(u.slice(0, comma))?.[1] || 'image/jpeg';
  const bin = atob(u.slice(comma + 1));
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Blob([bytes], { type: mime });
}

const blobToDataUrl = (blob) => new Promise((res, rej) => {
  const r = new FileReader();
  r.onload = () => res(r.result);
  r.onerror = () => rej(r.error);
  r.readAsDataURL(blob);
});

async function applyRoom(rec) {
  try {
    const next = rec?.dataUrl ? await createImageBitmap(dataUrlToBlob(rec.dataUrl)) : null;
    try { roomBitmap?.close(); } catch {}
    roomBitmap = next;
    roomVersion++;
  } catch (err) {
    console.warn('[Snap Vanish] could not read the empty-room photo', err);
  }
}

function loadRoom() {
  if (typeof chrome === 'undefined' || !chrome.storage?.local) return;
  chrome.storage.local.get('emptyRoom', (r) => applyRoom(r?.emptyRoom));
  chrome.storage.onChanged.addListener((changes, area) => {
    if (area === 'local' && changes.emptyRoom) applyRoom(changes.emptyRoom.newValue);
  });
}

// Draw the photo "cover" style (fills the frame, centre-cropped) at camera size.
function rebuildRoom(ctx) {
  ctx.roomVer = roomVersion;
  ctx.roomReady = !!roomBitmap;
  ctx.roomCtx.clearRect(0, 0, ctx.W, ctx.H);
  if (!roomBitmap) return;
  const { W, H } = ctx, iw = roomBitmap.width, ih = roomBitmap.height;
  const s = Math.max(W / iw, H / ih);
  const dw = iw * s, dh = ih * s;
  ctx.roomCtx.drawImage(roomBitmap, (W - dw) / 2, (H - dh) / 2, dw, dh);
}

// ---- "Capture empty room" -------------------------------------------------------
// Countdown -> wait until the segmenter sees nobody -> average a few frames
// (removes camera noise) -> save as a JPEG. Everything shown during this
// (countdown text) is drawn into the video, so do it before a call.
const CAP_COUNTDOWN_MS = 5000, CAP_WAIT_MS = 12000, CAP_FRAMES = 8, CAP_CLEAR_FRAC = 0.02;
const CAP = { state: 'idle', ctx: null, t0: 0, waitFrom: 0, clear: 0, n: 0, skip: 0, sum: null, msg: '', msgUntil: 0 };

function notice(msg, ms, now = performance.now()) {
  CAP.msg = msg;
  CAP.msgUntil = now + ms;
}

function startCapture(ctx, now) {
  if (CAP.state !== 'idle') return;
  Object.assign(CAP, { state: 'countdown', ctx, t0: now, clear: 0, n: 0, skip: 0, sum: null });
}

function failCapture(text, now) {
  CAP.state = 'idle';
  CAP.sum = null;
  notice(text, 5000, now);
}

function stepCapture(ctx, bitmap, now) {
  if (CAP.state === 'idle' || CAP.ctx !== ctx) return;
  const { W, H } = ctx;
  const N = ctx.person.length;
  if (CAP.state === 'countdown') {
    if (now - CAP.t0 >= CAP_COUNTDOWN_MS) { CAP.state = 'waiting'; CAP.waitFrom = now; CAP.clear = 0; }
    return;
  }
  if (CAP.state === 'waiting') {
    let s = 0;
    for (let i = 0; i < N; i++) s += ctx.person[i];
    if (ctx.frameUsable && s / N < CAP_CLEAR_FRAC) CAP.clear++; else CAP.clear = 0;
    if (CAP.clear >= 8) {
      CAP.state = 'grabbing';
      CAP.sum = new Uint16Array(W * H * 4);
      CAP.n = 0;
      CAP.skip = 0;
    } else if (now - CAP.waitFrom > CAP_WAIT_MS) {
      failCapture('Someone is still in view. Try again, or upload a photo.', now);
    }
    return;
  }
  if (CAP.state === 'grabbing') {
    if (CAP.sum.length !== W * H * 4) return failCapture('Camera size changed. Try again.', now);
    if (CAP.skip++ % 2) return; // spread the frames out a little
    const t = ctx.tmpCtx;
    t.globalCompositeOperation = 'copy';
    t.drawImage(bitmap, 0, 0);
    t.globalCompositeOperation = 'source-over';
    const d = t.getImageData(0, 0, W, H).data;
    const sum = CAP.sum;
    for (let i = 0; i < d.length; i++) sum[i] += d[i];
    if (++CAP.n >= CAP_FRAMES) finishCapture(W, H, now);
  }
}

function finishCapture(W, H, now) {
  const { sum, n } = CAP;
  const px = new Uint8ClampedArray(W * H * 4);
  for (let i = 0; i < px.length; i++) px[i] = Math.round(sum[i] / n);
  const [c, cx] = canvas2d(W, H);
  cx.putImageData(new ImageData(px, W, H), 0, 0);
  CAP.state = 'saving';
  CAP.sum = null;
  c.convertToBlob({ type: 'image/jpeg', quality: 0.92 })
    .then(blobToDataUrl)
    .then((dataUrl) => chrome.storage.local.set({ emptyRoom: { dataUrl, updatedAt: Date.now(), source: 'capture', width: W, height: H } }))
    .then(() => { CAP.state = 'idle'; notice('Empty room saved. You can step back in.', 3500); })
    .catch((err) => { console.warn('[Snap Vanish] saving room photo failed', err); failCapture('Could not save the photo.', performance.now()); });
}

function drawBanner(ctx, text) {
  const o = ctx.outCtx, { W, H } = ctx;
  const fs = Math.max(16, Math.round(W / 26));
  o.save();
  o.font = `700 ${fs}px system-ui, sans-serif`;
  o.textAlign = 'center';
  o.textBaseline = 'middle';
  const w = Math.min(W * 0.96, o.measureText(text).width + fs * 1.6);
  o.fillStyle = 'rgba(0,0,0,0.65)';
  o.fillRect((W - w) / 2, H / 2 - fs * 1.1, w, fs * 2.2);
  o.fillStyle = '#fff';
  o.fillText(text, W / 2, H / 2, W * 0.94);
  o.restore();
}

function drawCaptureOverlay(ctx, now) {
  if (CAP.state !== 'idle' && CAP.ctx === ctx) {
    if (CAP.state === 'countdown') drawBanner(ctx, `Step out of view… ${Math.max(1, Math.ceil((CAP_COUNTDOWN_MS - (now - CAP.t0)) / 1000))}`);
    else if (CAP.state === 'waiting') drawBanner(ctx, 'Waiting for the frame to be empty…');
    else drawBanner(ctx, 'Capturing the room…');
  } else if (now < CAP.msgUntil) {
    drawBanner(ctx, CAP.msg);
  }
}

// How much of the whole frame (not just your body) is already the room photo.
// Ramps up at the end of the vanish so the hand-over to the pure photo has no pop,
// and ramps back down right when you reappear.
function stillMix(ctx, now) {
  switch (ctx.state) {
    case 'hidden': return 1;
    case 'vanishing': return smoothstep(0.55, 1, (now - ctx.t0) / 1000 / effectDuration());
    case 'appearing': return 1 - smoothstep(0, 0.45, (now - ctx.t0) / 1000);
    default: return 0;
  }
}

// ---- Helpers ----------------------------------------------------------------
function hash2(x, y, seed) {
  let h = Math.imul(x, 374761393) ^ Math.imul(y, 668265263) ^ Math.imul(seed, 1442695041);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}
function valueNoise(x, y, seed) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
  const a = hash2(xi, yi, seed), b = hash2(xi + 1, yi, seed);
  const c = hash2(xi, yi + 1, seed), d = hash2(xi + 1, yi + 1, seed);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}
function fbm(x, y, seed) {
  return 0.5 * valueNoise(x, y, seed) + 0.3 * valueNoise(x * 2.3, y * 2.3, seed + 7) + 0.2 * valueNoise(x * 5.1, y * 5.1, seed + 13);
}

// Separable max filter (dilation) with radius r.
function dilate(src, dst, tmp, w, h, r) {
  for (let y = 0; y < h; y++) {
    const row = y * w;
    for (let x = 0; x < w; x++) {
      let m = 0;
      const x0 = Math.max(0, x - r), x1 = Math.min(w - 1, x + r);
      for (let k = x0; k <= x1; k++) if (src[row + k] > m) m = src[row + k];
      tmp[row + x] = m;
    }
  }
  for (let x = 0; x < w; x++) {
    for (let y = 0; y < h; y++) {
      let m = 0;
      const y0 = Math.max(0, y - r), y1 = Math.min(h - 1, y + r);
      for (let k = y0; k <= y1; k++) if (tmp[k * w + x] > m) m = tmp[k * w + x];
      dst[y * w + x] = m;
    }
  }
}

function windVector() {
  switch (config.wind) {
    case 'left': return [-1, -0.35];
    case 'up': return [0.15, -1];
    default: return [1, -0.35];
  }
}

const canvas2d = (w, h, opts) => {
  const c = new OffscreenCanvas(w, h);
  return [c, c.getContext('2d', opts)];
};

// ---- Per camera stream state -----------------------------------------------
class StreamCtx {
  constructor(id) {
    this.id = id;
    this.W = 0;
    this.H = 0;
    this.state = 'visible';
    this.t0 = 0;
    this.cooldownUntil = 0;
    this.snap = new SnapDetector();
    this.lastHands = [];
    this.frameNo = 0;
    this.lastFrameAt = 0;
    this.fps = 0;
    this.procMs = 0;
    // particles (structure of arrays, particle-canvas pixel units)
    const P = MAX_PARTICLES;
    this.pCount = 0;
    this.px = new Float32Array(P); this.py = new Float32Array(P);
    this.pvx = new Float32Array(P); this.pvy = new Float32Array(P);
    this.psx = new Float32Array(P); this.psy = new Float32Array(P);
    this.ptx = new Float32Array(P); this.pty = new Float32Array(P);
    this.page = new Float32Array(P); this.plife = new Float32Array(P);
    this.pacc = new Float32Array(P); this.pseed = new Float32Array(P);
    this.pcol = new Uint32Array(P); this.pmode = new Uint8Array(P);
  }

  resize(W, H) {
    this.W = W; this.H = H;
    const gw = GW, gh = Math.max(2, Math.round(GW * H / W));
    this.GW = gw; this.GH = gh;
    const N = gw * gh;
    [this.out, this.outCtx] = canvas2d(W, H);
    [this.small, this.smallCtx] = canvas2d(gw, gh, { willReadFrequently: true });
    const hw = Math.min(HAND_W, W), hh = Math.round(hw * H / W);
    [this.handCanvas, this.handCtx] = canvas2d(hw, hh);
    [this.tmp, this.tmpCtx] = canvas2d(W, H);
    [this.room, this.roomCtx] = canvas2d(W, H);
    this.roomVer = -1;
    this.roomReady = false;
    [this.hideCanvas, this.hideCtx] = canvas2d(gw, gh);
    this.hideImg = this.hideCtx.createImageData(gw, gh);
    this.PW = gw * 2; this.PH = gh * 2;
    [this.partCanvas, this.partCtx] = canvas2d(this.PW, this.PH);
    this.partImg = this.partCtx.createImageData(this.PW, this.PH);
    this.partBuf = new Uint32Array(this.partImg.data.buffer);
    this.mask = new Float32Array(N);
    this.person = new Float32Array(N);
    this.personD = new Float32Array(N);
    this.scratch = new Float32Array(N);
    this.scratch2 = new Float32Array(N);
    this.hideMask = new Float32Array(N);
    this.dilateTmp = new Float32Array(N);
    this.motion = new Uint8Array(N);
    this.history = new Float32Array(N);
    this.zone = new Float32Array(N);
    this.prevHide = new Float32Array(N);
    this.prevSmall = null;
    this.hn = new Float32Array(N);
    this.spawned = new Uint8Array(N);
    this.pCount = 0;
    this.setState('visible');
  }

  setState(s) {
    if (this.state === s) return;
    this.state = s;
    post({ type: 'state', state: s });
  }
}

// ---- Frame processing -------------------------------------------------------
function processFrame(ctx, bitmap, now) {
  if (bitmap.width !== ctx.W || bitmap.height !== ctx.H) ctx.resize(bitmap.width, bitmap.height);
  const { W, H, GW: gw, GH: gh } = ctx;
  const N = gw * gh;
  ctx.frameNo++;
  const dt = ctx.lastFrameAt ? Math.min(0.1, (now - ctx.lastFrameAt) / 1000) : 1 / 30;
  ctx.lastFrameAt = now;
  ctx.fps = ctx.fps * 0.9 + (1 / Math.max(dt, 1e-3)) * 0.1;
  const ts = nextTs();

  // 1. segmentation
  const modelStart = performance.now();
  ctx.smallCtx.drawImage(bitmap, 0, 0, gw, gh);
  segmenter.segmentForVideo(ctx.small, ts, (res) => {
    const masks = res.confidenceMasks;
    if (!masks?.length) return;
    const m = masks[masks.length - 1];
    const arr = m.getAsFloat32Array();
    if (m.width === gw && m.height === gh) {
      ctx.mask.set(arr);
    } else {
      for (let y = 0; y < gh; y++) {
        const sy = Math.min(m.height - 1, Math.floor(y * m.height / gh));
        for (let x = 0; x < gw; x++) {
          ctx.mask[y * gw + x] = arr[sy * m.width + Math.min(m.width - 1, Math.floor(x * m.width / gw))];
        }
      }
    }
  });
  // Low-res copy of this frame: particle colours + motion detection.
  const px = ctx.smallCtx.getImageData(0, 0, gw, gh).data;
  const prev = ctx.prevSmall;
  ctx.smallPixels = px;
  ctx.smallPixelsFrame = ctx.frameNo;
  // Cameras often deliver black or blank frames while starting up (or when
  // briefly covered). Never trust the body mask from those.
  let lumSum = 0, lumSq = 0;
  for (let i = 0; i < N; i++) {
    const lum = (px[i * 4] + px[i * 4 + 1] + px[i * 4 + 2]) / 3;
    lumSum += lum;
    lumSq += lum * lum;
  }
  const lumMean = lumSum / N;
  const lumStd = Math.sqrt(Math.max(0, lumSq / N - lumMean * lumMean));
  ctx.frameUsable = lumMean > 14 && lumStd > 5;
  for (let i = 0; i < N; i++) {
    const m = ctx.mask[i];
    ctx.person[i] = smoothstep(0.2, 0.55, m);
    ctx.scratch2[i] = smoothstep(0.04, 0.3, m);
    let moving = false;
    if (prev) {
      const j = i * 4;
      moving = Math.abs(px[j] - prev[j]) + Math.abs(px[j + 1] - prev[j + 1]) + Math.abs(px[j + 2] - prev[j + 2]) > 45;
    }
    ctx.motion[i] = moving ? 1 : 0;
    // where the body has been over the last couple of seconds
    if (ctx.frameUsable) {
      const hv = ctx.history[i] * 0.97;
      ctx.history[i] = ctx.person[i] > hv ? ctx.person[i] : hv;
    }
  }
  ctx.prevSmall = px;
  // A change across much of the image at once (lights, exposure, camera
  // bumped) is not you moving: ignore motion for this frame.
  let moved = 0;
  for (let i = 0; i < N; i++) moved += ctx.motion[i];
  ctx.globalChange = moved > N * 0.25;
  if (ctx.globalChange) ctx.motion.fill(0);
  dilate(ctx.person, ctx.personD, ctx.dilateTmp, gw, gh, 1);
  dilate(ctx.scratch2, ctx.hideMask, ctx.dilateTmp, gw, gh, 2);

  // 2. empty-room photo (capture routine + keep the photo sized to the camera)
  if (ctx.roomVer !== roomVersion) rebuildRoom(ctx);
  stepCapture(ctx, bitmap, now);

  // 3. snap detection
  if (config.gesture && (ctx.state === 'visible' || ctx.state === 'hidden') && now > ctx.cooldownUntil) {
    detectSnap(ctx, ts, now, bitmap);
  } else {
    ctx.lastHands = [];
    ctx.snap.reset();
  }
  recordModelTime(performance.now() - modelStart);

  // 4. effect
  // On black/blank camera frames there is nobody to hide and the body mask is
  // garbage, so just pass the frame through (the effect timeline still runs).
  const effectHide = advanceEffect(ctx, now);
  const hideAmount = ctx.frameUsable ? effectHide : null;
  const o = ctx.outCtx;
  o.globalCompositeOperation = 'copy';
  o.drawImage(bitmap, 0, 0);
  o.globalCompositeOperation = 'source-over';

  if (ctx.roomReady && ctx.state === 'hidden') {
    // Fully vanished: output is purely the real photo. No live pixels, no
    // masks, so there is nothing that can look patched or generated.
    o.drawImage(ctx.room, 0, 0);
    if (ctx.prevHideDirty) { ctx.prevHide.fill(0); ctx.prevHideDirty = false; }
  } else if (ctx.roomReady && hideAmount) {
    const mix = stillMix(ctx, now);
    // Fast, motion-blurred hands are often missed by the segmenter. Treat any
    // movement near where the body recently was as body too, and hold the
    // mask briefly so it does not flicker.
    for (let i = 0; i < N; i++) ctx.dilateTmp[i] = ctx.history[i] > 0.2 ? 1 : 0;
    dilate(ctx.dilateTmp, ctx.zone, ctx.scratch, gw, gh, 10);
    // Moving pixels near the body seed a flood fill through all connected
    // motion, so a blurred arm swinging far from the body is caught too.
    for (let i = 0; i < N; i++) ctx.scratch2[i] = ctx.motion[i];
    dilate(ctx.scratch2, ctx.dilateTmp, ctx.scratch, gw, gh, 2); // bridge small gaps
    // Breadth-first, limited to ~an arm's length from the body and to a
    // sane total area, so camera noise can never spread it across the frame.
    const queue = ctx.floodQueue || (ctx.floodQueue = new Int32Array(N));
    const dist = ctx.floodDist || (ctx.floodDist = new Uint8Array(N));
    const maxDist = Math.round(gw * 0.18), maxArea = N * 0.2;
    let qh = 0, qt = 0;
    for (let i = 0; i < N; i++) {
      ctx.scratch2[i] = 0;
      if (ctx.dilateTmp[i] && ctx.zone[i]) { ctx.scratch2[i] = 1; dist[i] = 0; queue[qt++] = i; }
    }
    while (qh < qt && qt < maxArea) {
      const i = queue[qh++];
      if (dist[i] >= maxDist) continue;
      const x = i % gw, y = (i / gw) | 0;
      for (let dy = -1; dy <= 1; dy++) {
        const yy = y + dy;
        if (yy < 0 || yy >= gh) continue;
        for (let dx = -1; dx <= 1; dx++) {
          const xx = x + dx;
          if (xx < 0 || xx >= gw) continue;
          const j = yy * gw + xx;
          if (!ctx.scratch2[j] && ctx.dilateTmp[j]) { ctx.scratch2[j] = 1; dist[j] = dist[i] + 1; queue[qt++] = j; }
        }
      }
    }
    dilate(ctx.scratch2, ctx.zone, ctx.scratch, gw, gh, 3);
    for (let i = 0; i < N; i++) {
      const v = Math.max(ctx.hideMask[i], ctx.zone[i], ctx.prevHide[i] * 0.8);
      ctx.hideMask[i] = v;
      ctx.prevHide[i] = v;
    }
    ctx.prevHideDirty = true;
    // Photo opacity per cell: the dissolved part of the body shows the photo,
    // and everything that is NOT body slowly becomes the photo too (stillMix),
    // so the final hand-over to the pure photo is seamless.
    const a = ctx.hideImg.data;
    let any = false;
    for (let i = 0; i < N; i++) {
      const hm = ctx.hideMask[i];
      const v = Math.min(1, hm * hideAmount(i) + (1 - hm) * mix);
      a[i * 4 + 3] = v * 255;
      if (v > 0) any = true;
    }
    if (any) {
      ctx.hideCtx.putImageData(ctx.hideImg, 0, 0);
      const t = ctx.tmpCtx;
      t.globalCompositeOperation = 'copy';
      t.drawImage(ctx.room, 0, 0);
      t.globalCompositeOperation = 'destination-in';
      t.drawImage(ctx.hideCanvas, 0, 0, W, H);
      t.globalCompositeOperation = 'source-over';
      o.drawImage(ctx.tmp, 0, 0);
    }
  }

  if (!ctx.roomReady || (!hideAmount && ctx.state !== 'hidden')) {
    if (ctx.prevHideDirty) { ctx.prevHide.fill(0); ctx.prevHideDirty = false; }
  }

  if (ctx.pCount) {
    stepParticles(ctx, dt, now / 1000);
    o.imageSmoothingEnabled = false;
    o.drawImage(ctx.partCanvas, 0, 0, W, H);
    o.imageSmoothingEnabled = true;
  }

  drawCaptureOverlay(ctx, now);
  if (config.debug) drawDebug(ctx, now);
  return ctx.out.transferToImageBitmap();
}

// ---- Snap detection ---------------------------------------------------------
function detectSnap(ctx, ts, now, bitmap) {
  const hc = ctx.handCanvas;
  ctx.handCtx.drawImage(bitmap, 0, 0, hc.width, hc.height);
  const res = handLandmarker.detectForVideo(hc, ts);
  ctx.lastHands = res.landmarks || [];
  const hands = ctx.lastHands.map((lm, k) => ({ lm, score: res.handedness?.[k]?.[0]?.score ?? 0 }));
  const snapped = ctx.snap.update(hands, {
    aspect: ctx.W / ctx.H, now, sensitivity: config.sensitivity, audioPeakAt, useAudio: config.audioAssist,
  });
  if (snapped) {
    ctx.lastSnapAt = now;
    ctx.lastSnapReason = ctx.snap.reason;
    trigger(ctx, 'toggle', now);
  }
}

// ---- Effect state machine ---------------------------------------------------
function trigger(ctx, action, now) {
  if (!ctx.W) return;
  if (action === 'toggle') action = ctx.state === 'visible' ? 'vanish' : ctx.state === 'hidden' ? 'appear' : null;
  if ((action === 'vanish' || action === 'appear') && !roomBitmap) {
    notice('No empty-room photo yet. Open Snap Vanish and capture or upload one.', 4500, now);
    return;
  }
  if (action === 'vanish' && ctx.state === 'visible') {
    prepareDissolve(ctx);
    ctx.state = null;
    ctx.setState('vanishing');
  } else if (action === 'appear' && ctx.state === 'hidden') {
    prepareDissolve(ctx);
    ctx.state = null;
    ctx.setState('appearing');
  } else {
    return;
  }
  ctx.t0 = now;
  ctx.spawned.fill(0);
  ctx.cooldownUntil = now + (effectDuration() + FLIGHT) * 1000 + 1200;
}

const effectDuration = () => Math.max(0.6, Math.min(6, Number(config.duration) || 2.4));

// Per-cell dissolve order: fractal noise blended with a sweep along the wind,
// normalised over the cells the person currently covers.
function prepareDissolve(ctx) {
  const { GW: gw, GH: gh, hn, personD } = ctx;
  const seed = (Math.random() * 1e6) | 0;
  const [wx, wy] = windVector();
  const len = Math.hypot(wx, wy);
  let lo = Infinity, hi = -Infinity;
  for (let y = 0; y < gh; y++) {
    for (let x = 0; x < gw; x++) {
      const i = y * gw + x;
      const proj = -((x / gw) * wx + (y / gh) * wy) / len; // downwind side goes first
      const v = 0.62 * fbm(x / gw * 7, y / gw * 7, seed) + 0.38 * proj;
      hn[i] = v;
      if (personD[i] > 0.3) { if (v < lo) lo = v; if (v > hi) hi = v; }
    }
  }
  if (!(hi > lo)) {
    lo = Infinity; hi = -Infinity;
    for (let i = 0; i < hn.length; i++) { if (hn[i] < lo) lo = hn[i]; if (hn[i] > hi) hi = hn[i]; }
  }
  const span = hi - lo || 1;
  for (let i = 0; i < hn.length; i++) hn[i] = clamp01((hn[i] - lo) / span);
}

// Returns a function giving how hidden each grid cell is (0..1), or null when
// nothing is hidden. Spawns particles as the dissolve front advances.
function advanceEffect(ctx, now) {
  const D = effectDuration();
  const { hn, spawned, person } = ctx;
  const N = hn.length;
  switch (ctx.state) {
    case 'visible':
      return null;
    case 'hidden':
      return () => 1;
    case 'vanishing': {
      const t = (now - ctx.t0) / 1000 / D;
      for (let i = 0; i < N; i++) {
        if (!spawned[i] && hn[i] <= t) {
          spawned[i] = 1;
          if (person[i] > 0.35) spawnOut(ctx, i);
        }
      }
      if (t >= 1) {
        ctx.setState('hidden');
        return () => 1;
      }
      return (i) => (hn[i] <= t ? 1 : 0);
    }
    case 'appearing': {
      const Da = D * 0.8;
      const tau = (now - ctx.t0) / 1000;
      for (let i = 0; i < N; i++) {
        if (!spawned[i] && hn[i] * Da <= tau) {
          spawned[i] = 1;
          if (person[i] > 0.35) spawnIn(ctx, i);
        }
      }
      if (tau >= Da + FLIGHT + 0.05) {
        ctx.setState('visible');
        return null;
      }
      return (i) => (tau < hn[i] * Da + FLIGHT ? 1 : 0);
    }
  }
  return null;
}

function cellColor(ctx, i) {
  // ctx.small already holds this frame downscaled to the grid
  if (!ctx.smallPixels || ctx.smallPixelsFrame !== ctx.frameNo) {
    ctx.smallPixels = ctx.smallCtx.getImageData(0, 0, ctx.GW, ctx.GH).data;
    ctx.smallPixelsFrame = ctx.frameNo;
  }
  const p = ctx.smallPixels;
  return [p[i * 4], p[i * 4 + 1], p[i * 4 + 2]];
}

function addParticle(ctx) {
  if (ctx.pCount >= MAX_PARTICLES) return -1;
  return ctx.pCount++;
}

function spawnOut(ctx, i) {
  const [r, g, b] = cellColor(ctx, i);
  const gx = i % ctx.GW, gy = (i / ctx.GW) | 0;
  const [wx, wy] = windVector();
  for (let k = 0; k < 2; k++) {
    const p = addParticle(ctx);
    if (p < 0) return;
    ctx.px[p] = gx * 2 + Math.random() * 2;
    ctx.py[p] = gy * 2 + Math.random() * 2;
    const v0 = rand(4, 22);
    ctx.pvx[p] = wx * v0 + rand(-12, 12);
    ctx.pvy[p] = wy * v0 + rand(-12, 12);
    ctx.pacc[p] = rand(50, 170);
    ctx.pseed[p] = Math.random() * 100;
    ctx.page[p] = 0;
    ctx.plife[p] = rand(1.0, 2.3);
    ctx.pmode[p] = 0;
    ctx.pcol[p] = (r << 16) | (g << 8) | b;
  }
}

function spawnIn(ctx, i) {
  const [r, g, b] = cellColor(ctx, i);
  const gx = i % ctx.GW, gy = (i / ctx.GW) | 0;
  const [wx, wy] = windVector();
  for (let k = 0; k < 2; k++) {
    const p = addParticle(ctx);
    if (p < 0) return;
    const tx = gx * 2 + Math.random() * 2, ty = gy * 2 + Math.random() * 2;
    const dist = rand(50, 170);
    ctx.ptx[p] = tx; ctx.pty[p] = ty;
    ctx.psx[p] = tx + wx * dist + rand(-30, 30);
    ctx.psy[p] = ty + wy * dist + rand(-30, 30);
    ctx.px[p] = ctx.psx[p]; ctx.py[p] = ctx.psy[p];
    ctx.pseed[p] = rand(-1, 1);
    ctx.page[p] = 0;
    ctx.plife[p] = FLIGHT;
    ctx.pmode[p] = 1;
    ctx.pcol[p] = (r << 16) | (g << 8) | b;
  }
}

const ASH = [74, 64, 56];

function stepParticles(ctx, dt, T) {
  const { PW, PH, partBuf: buf } = ctx;
  const [wx, wy] = windVector();
  buf.fill(0);
  let n = ctx.pCount;
  for (let p = 0; p < n; p++) {
    ctx.page[p] += dt;
    const age = ctx.page[p], life = ctx.plife[p];
    if (age >= life) {
      // swap-remove
      n--;
      ctx.px[p] = ctx.px[n]; ctx.py[p] = ctx.py[n];
      ctx.pvx[p] = ctx.pvx[n]; ctx.pvy[p] = ctx.pvy[n];
      ctx.psx[p] = ctx.psx[n]; ctx.psy[p] = ctx.psy[n];
      ctx.ptx[p] = ctx.ptx[n]; ctx.pty[p] = ctx.pty[n];
      ctx.page[p] = ctx.page[n]; ctx.plife[p] = ctx.plife[n];
      ctx.pacc[p] = ctx.pacc[n]; ctx.pseed[p] = ctx.pseed[n];
      ctx.pcol[p] = ctx.pcol[n]; ctx.pmode[p] = ctx.pmode[n];
      p--;
      continue;
    }
    const k = age / life;
    let x, y, alpha, big, ashMix;
    if (ctx.pmode[p] === 0) {
      const s = ctx.pseed[p];
      const ax = wx * ctx.pacc[p] + Math.sin(ctx.py[p] * 0.09 + T * 2.1 + s) * 45;
      const ay = wy * ctx.pacc[p] + Math.cos(ctx.px[p] * 0.07 - T * 1.7 + s) * 35;
      ctx.pvx[p] = (ctx.pvx[p] + ax * dt) * 0.985;
      ctx.pvy[p] = (ctx.pvy[p] + ay * dt) * 0.985;
      x = ctx.px[p] += ctx.pvx[p] * dt;
      y = ctx.py[p] += ctx.pvy[p] * dt;
      alpha = 1 - k * k;
      big = k < 0.3;
      ashMix = Math.min(0.8, k * 1.15);
    } else {
      const e = k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2;
      const sw = Math.sin(k * Math.PI) * 18 * ctx.pseed[p];
      const dx = ctx.ptx[p] - ctx.psx[p], dy = ctx.pty[p] - ctx.psy[p];
      const len = Math.hypot(dx, dy) || 1;
      x = ctx.psx[p] + dx * e - (dy / len) * sw;
      y = ctx.psy[p] + dy * e + (dx / len) * sw;
      alpha = Math.min(1, k * 2.5);
      big = k > 0.6;
      ashMix = Math.max(0, 0.8 - k * 1.2);
    }
    const xi = x | 0, yi = y | 0;
    if (xi < 0 || yi < 0 || xi >= PW || yi >= PH || alpha <= 0) continue;
    const c = ctx.pcol[p];
    const r = ((c >> 16) & 255) * (1 - ashMix) + ASH[0] * ashMix;
    const g = ((c >> 8) & 255) * (1 - ashMix) + ASH[1] * ashMix;
    const b = (c & 255) * (1 - ashMix) + ASH[2] * ashMix;
    const px = (((alpha * 255) & 255) << 24) | ((b & 255) << 16) | ((g & 255) << 8) | (r & 255);
    const idx = yi * PW + xi;
    buf[idx] = px;
    if (big && xi + 1 < PW && yi + 1 < PH) {
      buf[idx + 1] = px; buf[idx + PW] = px; buf[idx + PW + 1] = px;
    }
  }
  ctx.pCount = n;
  ctx.partCtx.putImageData(ctx.partImg, 0, 0);
}

// ---- Debug overlay ----------------------------------------------------------
const HAND_EDGES = [[0, 1], [1, 2], [2, 3], [3, 4], [0, 5], [5, 6], [6, 7], [7, 8], [5, 9], [9, 10], [10, 11], [11, 12],
  [9, 13], [13, 14], [14, 15], [15, 16], [13, 17], [17, 18], [18, 19], [19, 20], [0, 17]];

function drawDebug(ctx, now) {
  const o = ctx.outCtx, { W, H } = ctx;
  o.save();
  o.lineWidth = Math.max(2, W / 400);
  for (const lm of ctx.lastHands) {
    o.strokeStyle = 'rgba(0,255,180,0.9)';
    o.beginPath();
    for (const [a, b] of HAND_EDGES) {
      o.moveTo(lm[a].x * W, lm[a].y * H);
      o.lineTo(lm[b].x * W, lm[b].y * H);
    }
    o.stroke();
    o.fillStyle = '#ff3b6b';
    for (const j of [4, 12]) { o.beginPath(); o.arc(lm[j].x * W, lm[j].y * H, W / 160, 0, 7); o.fill(); }
  }
  const lines = [`state: ${ctx.state}   fps: ${ctx.fps.toFixed(0)}   ${ctx.procMs.toFixed(0)} ms/frame   ${bench.choice || bench.phase}   particles: ${ctx.pCount}`];
  ctx.snap.info.forEach((h, i) => {
    const tag = !h.usable ? '  (ignored: too low/small/unsure)' : h.loadedPose ? '  LOADED' : '';
    lines.push(`hand ${i + 1}: thumb-middle ${h.tm.toFixed(2)}  middle-wrist ${h.mw.toFixed(2)}${tag}`);
  });
  if (ctx.snap.armed) lines.push('ARMED: snap now');
  if (now - (ctx.lastSnapAt || -1e9) < 1500) lines.push(`SNAP detected (${ctx.lastSnapReason})`);
  if (now - audioPeakAt < 400) lines.push('audio: SNAP CLICK');
  if (now < ctx.cooldownUntil) lines.push('cooldown');
  lines.push(roomBitmap ? `empty-room photo: loaded (${roomBitmap.width}x${roomBitmap.height})` : 'empty-room photo: NONE');
  const fs = Math.max(12, Math.round(W / 60));
  o.font = `600 ${fs}px system-ui, sans-serif`;
  o.fillStyle = 'rgba(0,0,0,0.55)';
  o.fillRect(0, 0, W * 0.62, fs * 1.4 * lines.length + fs * 0.6);
  o.fillStyle = '#fff';
  lines.forEach((l, i) => o.fillText(l, fs * 0.5, fs * 1.4 * (i + 1)));
  o.restore();
}

// ---- Messaging --------------------------------------------------------------
window.addEventListener('message', (e) => {
  if (e.source !== PARENT) return;
  const d = e.data;
  if (!d || typeof d !== 'object') return;
  switch (d.type) {
    case 'frame': {
      if (!ready) {
        d.bitmap?.close();
        post({ type: 'pass', id: d.id });
        return;
      }
      let ctx = contexts.get(d.streamId);
      if (!ctx) contexts.set(d.streamId, (ctx = new StreamCtx(d.streamId)));
      try {
        const t = performance.now();
        const out = processFrame(ctx, d.bitmap, t);
        ctx.procMs = ctx.procMs ? ctx.procMs * 0.9 + (performance.now() - t) * 0.1 : performance.now() - t;
        post({ type: 'out', id: d.id, bitmap: out }, [out]);
      } catch (err) {
        console.error('[Snap Vanish] frame failed', err);
        post({ type: 'pass', id: d.id });
      } finally {
        d.bitmap.close();
      }
      break;
    }
    case 'config':
      config = { ...config, ...d.config };
      break;
    case 'trigger': {
      const now = performance.now();
      if (d.action === 'captureRoom') {
        const first = contexts.values().next().value;
        if (first) startCapture(first, now);
        break;
      }
      for (const ctx of contexts.values()) trigger(ctx, d.action, now);
      break;
    }
    case 'audioPeak':
      audioPeakAt = performance.now();
      break;
    case 'release':
      contexts.delete(d.streamId);
      break;
  }
});

init();
